          const members = [...this.files.values()].flatMap(candidate => candidate.callables
            .filter(item => item.kind === 'function' && item.fqcn.toLowerCase() === name.toLowerCase())
            .map(item => ({ uri: candidate.uri, start: item.start, fqcn: item.fqcn })));
